    "note_pedagogique": "Longue sourate mecquoise révélée, selon la tradition, d'un seul tenant, escortée d'anges. Elle démonte l'idolâtrie par l'argument et non par l'anathème : Abraham y cherche son Seigneur parmi l'astre, la lune et le soleil avant de tourner son visage « vers Celui qui a créé les cieux et la terre ». Elle tire son nom des bestiaux (anʿām) que les païens entouraient d'interdits inventés, et culmine dans le credo : « ma prière, mon sacrifice, ma vie et ma mort appartiennent à Allah, Seigneur des mondes ».",
